 dict(states='02,03,06-15 / E/W lower fabric',observation='Source has substantial irregular red lower outer folds; authored maps reduce these to small clean triangular corners, weakening native red/tan identity.',severity='medium',confidence='high',correction='Preserve source lower red region weight and irregular folded shape within fixed geometry/frame.'),
 dict(states='NS-bearing strips',observation='Native red strip markedly broader; authored ties visible but red presence extremely fine at intended size.',severity='medium',confidence='high',correction='Reconcile projected edge-on width and red/tan balance in common mapping.'),
