write(HERE/'independent-structural-review.json',report)
l=read(ROOT/'evidence/conversion-ledger.json');assert l['active_entry']=='SCN-CANVASWALL';e=next(e for e in l['entries'] if e['id']==l['active_entry']);now=datetime.now(timezone.utc).isoformat()
